static size_t operation_index(
	size_t initial_state, size_t sequence, size_t step,
	size_t count)
{
	size_t stride = 2U * (sequence % 8U) + 1U;

	return (initial_state + sequence + step * stride) % count;
}

static size_t condition_index(
	size_t initial_state, size_t sequence, size_t step,
	size_t multiplier, size_t count)
{
	return (initial_state * multiplier +
		sequence * (multiplier + 2U) +
		step * (multiplier + 4U)) % count;
}

size_t pqcp_channel_transition_catalog_count(void)
{
	return ARRAY_SIZE(channel_transition_fingerprints);
}

int pqcp_channel_transition_catalog_get(
	size_t index,
	struct pqcp_channel_transition_trace *trace)
{
	size_t initial_state;
	size_t sequence;

	if (index >= ARRAY_SIZE(channel_transition_fingerprints) ||
	    trace == NULL) {
		return -EINVAL;
	}
	initial_state =
		index / TRANSITION_SEQUENCES_PER_STATE;
	sequence = index % TRANSITION_SEQUENCES_PER_STATE;
	memset(trace, 0, sizeof(*trace));
	trace->schema_version =
		PQCP_OPERATION_TRANSITION_SCHEMA_VERSION;
	trace->trace_id =
		PQCP_OPERATION_TRANSITION_TRACE_ID(
			PQCP_OPERATION_TRANSITION_CHANNEL,
			initial_state, sequence);
	trace->initial_state =
		(enum pqcp_channel_policy_state)initial_state;
	trace->step_count =
		PQCP_OPERATION_TRANSITION_STEPS_PER_TRACE;
	for (size_t step = 0U;
	     step < trace->step_count; ++step) {
		trace->steps[step].control =
			(enum pqcp_channel_control_kind)
				operation_index(
					initial_state, sequence, step,
					PQCP_CHANNEL_POLICY_CONTROL_COUNT);
		trace->steps[step].path_condition =
			(enum pqcp_channel_path_condition)
				condition_index(
					initial_state, sequence, step, 7U,
					PQCP_CHANNEL_PATH_CONDITION_COUNT);
		trace->steps[step].fault_condition =
			(enum pqcp_channel_fault_condition)
				condition_index(
					initial_state, sequence, step, 9U,
					PQCP_CHANNEL_FAULT_CONDITION_COUNT);
	}
	trace->expected_fingerprint =
		channel_transition_fingerprints[index];
	return 0;
}
